// ===== L412-L427 api(path, options) 封装 =====
function decodeJwtPayload(token) {
  try {
    const payload = String(token || "").split(".")[1];
    if (!payload) return null;
    const normalized = payload.replace(/-/g, "+").replace(/_/g, "/");
    return JSON.parse(atob(normalized));
  } catch (_err) {
    return null;
  }
}

function getTokenExpiresAt(token) {
  const payload = decodeJwtPayload(token);
  return payload?.exp ? payload.exp * 1000 : 0;
}

function shouldRefreshTokenSoon() {
  const expiresAt = getTokenExpiresAt(state.token);
  return Boolean(expiresAt && expiresAt - Date.now() < 10 * 60 * 1000);
}

async function refreshAuthToken(options = {}) {
  if (!state.token) return false;
  if (state.authRefreshPromise) return state.authRefreshPromise;
  state.authRefreshPromise = (async () => {
    const response = await fetch("/api/auth/refresh", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${state.token}`,
        "Content-Type": "application/json"
      }
    });
    if (!response.ok) {
      if (!options.silent) await handleAuthExpired();
      return false;
    }
    const data = await response.json();
    if (data?.token) {
      state.token = data.token;
      state.user = data.user || state.user;
      state.authExpiredHandled = false;
      localStorage.setItem("lan_system_token", state.token);
      scheduleAuthRefresh();
      return true;
    }
    return false;
  })().finally(() => {
    state.authRefreshPromise = null;
  });
  return state.authRefreshPromise;
}

function scheduleAuthRefresh() {
  if (state.authRefreshTimer) clearTimeout(state.authRefreshTimer);
  const expiresAt = getTokenExpiresAt(state.token);
  if (!expiresAt) return;
  const delay = Math.max(30 * 1000, expiresAt - Date.now() - 10 * 60 * 1000);
  state.authRefreshTimer = setTimeout(() => {
    refreshAuthToken({ silent: true }).catch((err) => console.warn("[auth] refresh failed", err));
  }, delay);
}

async function saveActiveDraftBeforeRelogin() {
  const tasks = [];
  if (typeof savePostFormDraftNow === "function") {
    try { savePostFormDraftNow(); } catch (err) { console.warn("[auth] save post draft failed", err); }
  }
  if (typeof saveLeadDraftNow === "function") {
    tasks.push(saveLeadDraftNow().catch((err) => console.warn("[auth] save lead draft failed", err)));
  }
  await Promise.all(tasks);
}

async function handleAuthExpired() {
  if (state.authExpiredHandled) return;
  state.authExpiredHandled = true;
  await saveActiveDraftBeforeRelogin();
  alert("登录已失效，已尽量保存当前作品/客资草稿，请重新登录后继续提交。");
}

async function api(path, options = {}) {
  const isFormData = options.body instanceof FormData;
  if (state.token && !options.skipAuthRefresh && path !== "/api/auth/refresh" && shouldRefreshTokenSoon()) {
    await refreshAuthToken({ silent: true }).catch((err) => console.warn("[auth] preflight refresh failed", err));
  }
  const response = await fetch(path, {
    ...options,
    headers: {
      ...(state.token ? { Authorization: `Bearer ${state.token}` } : {}),
      ...(!isFormData ? { "Content-Type": "application/json" } : {}),
      ...(options.headers || {})
    }
  });
  if (!response.ok) {
    const data = await response.json().catch(() => ({ message: "请求失败" }));
    const error = new Error(data.message || "请求失败");
    error.status = response.status;
    error.data = data;
    if (response.status === 401 && !options.skipAuthExpiredHandler) {
      await handleAuthExpired();
    }
    throw error;
  }
  return response.json();
}
